export const meta = {
  name: 'sha256-generator-and-verifier',
  description: 'Build create-sha256-base.py + verify-graph.py against the frozen nodes.py, prove correct vs hashlib, then adversarially review',
  phases: [
    { title: 'Build', detail: 'implement generator + verifier; iterate until hashlib vectors pass' },
    { title: 'Review', detail: 'independent adversarial audits (4 lenses) + fresh empirical re-run' },
  ],
}

const CWD = 'D:\\Github\\SHA Exporer'

const CONTEXT = `
You are working in the git repo at "${CWD}" on Windows. Python is \`python\` (3.14).
READ FIRST: \`plan.md\` (canonical spec) and \`nodes.py\` (the FROZEN shared library). Do NOT modify nodes.py.

Locked conventions (from plan.md, restated so you don't guess):
- Single 512-bit block compressed with the fixed IV. K-* = the 64 round constants, H-* = the 8 initial hash values. Include the final feed-forward add that produces the digest. No multi-block, no padding inside the circuit.
- DERIVE the K and H constants from first principles in Python (K = first 32 fractional bits of cube roots of the first 64 primes; H = first 32 fractional bits of square roots of the first 8 primes). Do NOT paste them from memory — derive them, so a recall error is impossible.
- Bit ordering is BIG-ENDIAN, MSB-first. MESSAGE-000 = bit 7 (MSB) of byte 0; MESSAGE-007 = bit 0 of byte 0; MESSAGE-008 = MSB of byte 1; ... 32-bit word w = bytes 4w..4w+3 big-endian. HASH-000 = MSB of H0 (high bit of first hex nibble); HASH-031 = LSB of H0; HASH-255 = LSB of H7. Indices are zero-padded to 3 digits: MESSAGE-000..511, HASH-000..255.
- Build everything from NAND. NOT(a)=NAND(a,a); AND=NOT(NAND); OR=NAND(NOT a,NOT b); XOR(a,b)=t=NAND(a,b) then NAND(NAND(a,t),NAND(b,t)); full adder sum=a^b^cin, cout=majority; 32-bit add = 32 ripple full adders with cin0=const0, drop final carry (mod 2^32). ROTR/ROTL are FREE (wire relabeling, 0 gates); SHR is free but injects const 0 into vacated high bits.
- Favor SIMPLE, uniform, possibly-redundant construction (e.g. always emit full adders even when cin is constant 0) — the optimizer cleans up later. Let unexpected conditions crash.
- Build the graph using nodes.Graph / nodes.Node and serialize via Graph.write. The only free inputs in the final graph MUST be exactly MESSAGE-000..511. All 256 HASH-000..255 must exist as O (output) nodes. The graph must be acyclic with no undefined references other than MESSAGE-*.
`

const BUILD_RESULT = {
  type: 'object',
  additionalProperties: false,
  required: ['files_written', 'base_node_count', 'free_inputs_are_only_message', 'hash_outputs_count', 'vectors', 'all_passed', 'notes'],
  properties: {
    files_written: { type: 'array', items: { type: 'string' } },
    base_node_count: { type: 'integer' },
    free_inputs_are_only_message: { type: 'boolean' },
    hash_outputs_count: { type: 'integer' },
    vectors: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['message', 'expected', 'got', 'pass'],
        properties: {
          message: { type: 'string' }, expected: { type: 'string' },
          got: { type: 'string' }, pass: { type: 'boolean' },
        },
      },
    },
    all_passed: { type: 'boolean' },
    notes: { type: 'string' },
  },
}

const REVIEW = {
  type: 'object',
  additionalProperties: false,
  required: ['lens', 'overall', 'summary', 'issues'],
  properties: {
    lens: { type: 'string' },
    overall: { type: 'string', enum: ['pass', 'concerns', 'fail'] },
    summary: { type: 'string' },
    issues: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['severity', 'title', 'detail', 'evidence', 'suggested_fix'],
        properties: {
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          title: { type: 'string' },
          detail: { type: 'string' },
          evidence: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
      },
    },
  },
}

phase('Build')
const build = await agent(
  `${CONTEXT}

TASK — implement two files, then iterate until correct:

1. \`create-sha256-base.py\` — emits \`SHA256-base.nodes\` (use nodes.Graph). Translates SHA256 (single block, fixed IV) into NAND macros per the spec above.

2. \`verify-graph.py\` — a CLI verifier built on nodes.parse + nodes.evaluate:
   - evaluate mode: given a .nodes file and a message string (<=55 bytes), build the padded 64-byte single block (msg + 0x80 + zeros + uint64_be(bitlen)), set MESSAGE-* bits per the big-endian MSB-first mapping, evaluate, read HASH-* bits, format as a 64-char hex digest, and compare to hashlib.sha256(msg).hexdigest().
   - equivalence mode: given two .nodes files with identical free inputs and outputs, run K random input assignments through both and assert identical outputs. Smoke-test it (a graph equals itself; a deliberately mutated copy does not).

ITERATE: run \`python create-sha256-base.py\` then verify the messages "" , "abc", and one 55-byte message against hashlib. Fix bugs until ALL pass. Common pitfalls: MESSAGE/HASH bit endianness, adder carry direction, rotation vs shift, message-schedule indices (t-2,t-7,t-15,t-16), the final feed-forward add.

Also sanity-check with python one-liners: that nodes.parse('SHA256-base.nodes').free_inputs() == the 512 MESSAGE-* ids, that there are exactly 256 HASH-* output nodes, and that topo_order() succeeds (acyclic).

Return the structured result. "got"/"expected" are the full hex digests you observed.`,
  { label: 'build:generator+verifier', phase: 'Build', schema: BUILD_RESULT },
)

log(`Build: all_passed=${build.all_passed}, base nodes=${build.base_node_count}, hash outputs=${build.hash_outputs_count}`)

phase('Review')
const LENSES = [
  {
    key: 'endianness-interface',
    prompt: `Audit ONLY the input/output interface and bit ordering of create-sha256-base.py + verify-graph.py.
- Verify MESSAGE-* mapping is big-endian MSB-first exactly as specified (MESSAGE-000 = MSB of byte 0, etc.). Verify HASH-* mapping likewise (HASH-000 = MSB of H0).
- Confirm the ONLY free inputs in SHA256-base.nodes are MESSAGE-000..511 (run nodes.free_inputs()), and that all 256 HASH-000..255 exist as O nodes.
- Confirm the passing "abc"/"" digests genuinely discriminate (the verifier isn't accidentally comparing hashlib to itself or short-circuiting). Trace how a HASH bit flows back to outputs.
Provide concrete evidence (cite file:line, run python checks).`,
  },
  {
    key: 'arithmetic-macros',
    prompt: `Audit ONLY the boolean/arithmetic primitives in create-sha256-base.py.
- Extract each NAND macro (NOT, AND, OR, XOR) and the full adder; verify their truth tables by independent computation (build the sub-circuit and evaluate all input combos via nodes.evaluate, OR reason exhaustively).
- Verify the 32-bit adder is ripple, little-endian carry, drops the final carry (mod 2^32), and handles cin0.
- Verify ROTR/ROTL are implemented as 0-gate wire relabeling and SHR injects a constant-0 node into vacated bits (not a wraparound).
Provide concrete evidence.`,
  },
  {
    key: 'sha-structure',
    prompt: `Audit ONLY the SHA256 algorithm structure in create-sha256-base.py.
- Recompute the K (cube roots of first 64 primes) and H (sqrt of first 8 primes) constants from first principles in Python and confirm the code's constants/wiring match.
- Verify Sigma0/Sigma1/sigma0/sigma1 rotation+shift amounts (2/13/22, 6/11/25, 7/18/3, 17/19/10), Ch and Maj definitions, the message schedule recurrence indices (t-2,t-7,t-15,t-16), the round T1/T2 computation, the state-variable shift, and the final feed-forward add to the IV.
Provide concrete evidence (cite file:line).`,
  },
  {
    key: 'independent-empirical',
    prompt: `Do an INDEPENDENT empirical re-verification. Do NOT overwrite SHA256-base.nodes — if you regenerate, write to a temp path (e.g. SHA256-base.check.nodes) and delete it after.
- Using the existing SHA256-base.nodes and verify-graph.py, test EXTRA vectors NOT used during the build: a 55-byte message (max single block), and 3 random messages of varying length <=55 bytes. Compare every digest to hashlib.
- Structural sanity: acyclic (topo_order succeeds), reasonable node count, no undefined refs besides MESSAGE-*, all 256 HASH outputs present.
- Smoke-test verify-graph's equivalence mode.
Report exact digests (got vs hashlib) for each vector.`,
  },
]

const reviews = await parallel(LENSES.map(l => () =>
  agent(`${CONTEXT}\n\nThe build agent reported: all_passed=${build.all_passed}. Files: ${build.files_written.join(', ')}.\nReview the create-sha256-base.py and verify-graph.py SOURCE for logic; only sample/grep SHA256-base.nodes (it is large) via python, do not read it whole.\n\n${l.prompt}`,
    { label: `review:${l.key}`, phase: 'Review', schema: REVIEW })
    .then(r => ({ ...r, lens: l.key }))
))

const valid = reviews.filter(Boolean)
const allIssues = valid.flatMap(r => r.issues.map(i => ({ ...i, lens: r.lens })))
const critical = allIssues.filter(i => i.severity === 'critical')
const major = allIssues.filter(i => i.severity === 'major')

return {
  build,
  review_overall: valid.map(r => ({ lens: r.lens, overall: r.overall, summary: r.summary })),
  critical_issues: critical,
  major_issues: major,
  minor_issues: allIssues.filter(i => i.severity === 'minor'),
  verdict: build.all_passed && critical.length === 0 ? 'LIKELY_CORRECT' : 'NEEDS_FIXES',
}
